quests[72693] = { id = 72693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown Supplies", objectives = "Your victories against the Primalists have caught the attention of the Accord, {class}. They have decided to reward you handsomely... in the hopes you will continue fighting for the cause, of course. \n\nPlease, take this larger allotment of supplies. Use them to defend the Dragon Isles!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
