quests[72708] = { id = 72708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", description = "<That proto-dragon must've snatched this bag of supplies off of an unlucky Dragonscale Expedition member.\n\nCataloger Jakes in Wingrest Embassy will know what best to do with it.>", completion = "We're always looking for more supplies, and I know just what we can do with these.", objectives = "Deliver Dragon Isles Supply Bag to Cataloger Jakes in Wingrest Embassy.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72709] = { id = 72709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funding a Treasure Hunt", description = "<Cataloger Jakes quickly flips through her own supply bag and pulls out a freshly drawn map.>\n\nOne of our archeologists just reported some new findings in regards to a lost artifact, suspected to be in this area.\n\nIf you'll donate those supplies to fund the archeologist's next expedition, you can have this map that points to a nearby treasure.", progress = "Our archeologists love their work, but they still need funding to do it.", completion = "Rae'ana and I will be traveling with Toddy and Naleidea to our permanent basecamp, once they figure out where that's going to be.\n\nFind us there later to see our full catalog.", objectives = "Buy the Archeologist Artifact Notes from Cataloger Jakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72712] = { id = 72712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best We Have", completion = "You're here.\n\nGood.", objectives = "Talk with Talon Damos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72713] = { id = 72713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inheritance", description = "Glad you could make it, soldier.\n\n<Damos gives you a sardonic salute.>\n\nThis is surreal. We're back in a place we knew long ago. Now it's in ruins. And it's crawling with all kinds of new wildlife. \n\nI guess it's true what they say. You can never go home again.\n\nEnough talking. Time to work. Emberthal wants this place locked down.", completion = "Thanks for the assistance, {name}. You're a real asset in the field.\n\nAfter this is over, we should meet up in Valdrakken. I think there's a couple watering holes with our names on 'em.", objectives = "Help the dracthyr scouts secure the Lost Atheneum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72714] = { id = 72714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Interdisciplinary Approach", description = "The Dragonscale Expedition does not pose a threat to Sarkareth. The fact that Sarkareth and his followers would be so brazen as to attack them during their research...\n\n<Ebyssian furrows his brow.>\n\nSave as many Expedition members as you can. The knowledge in these ruins is priceless if it can unlock the secrets of our past, but it is ultimately worthless when weighed against the value of single innocent life.\n\nI will meet you in the ruins above when I am done here.", progress = "We must save as many folk as we can.", completion = "Well done, {name}. It gladdens me that you were able to save so many... and we are richer in knowledge because of it.", objectives = "Rescue 5 Frightened Researchers at Talonlords' Perch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72715] = { id = 72715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Flame at Bay", description = "It's not enough that Sarkareth kills our people, twists our heritage, and burns everything in his path. Now he seeks to pillage the creche of the Adamantine Vigil. \n\n<Emberthal snarls.>\n\nEbyssian and I will stay here while you push back the Sundered Flame. We'll meet you up top once the Expedition is secure.", progress = "Don't tell me you need to catch your breath.", completion = "There is no victory to celebrate this day. Every dead dracthyr is a tragedy that could have been... should have been avoided.\n\nOur hands run red with blood from our failures.", objectives = "Slay 4 Sundered Pillagers, 6 Sundered Ruinstalkers, and Winglord Iyazael in the High Creche.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72717] = { id = 72717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Creche Divided", description = "This place... I have not been here for a long time. Not since before I was a Scalecommander. \n\nIt is a dark place, full of pain... and failure. \n\nThis was where Neltharion tested those he considered most worthy of his attention. He poked and prodded us with powers we could not understand or control.\n\nMany of us were found... wanting.\n\nPerhaps Sarkareth brought me here to test me the same way our father tested us.\n\nWill you walk with me?", completion = "We have him cornered! \n\nThey aren't attacking... why? What trick is this?", objectives = "Help Emberthal explore the caves beneath Dragonskull Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72719] = { id = 72719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fel Path Through Time", description = "Think you're tough? I've read up on the Legion. Now they seem tough.\n\nWhy don't you show me if you're tougher than them?", progress = "I'm getting some big lifts in here. You do that task yet?", completion = "Look at you! Maybe you're tough after all. \n\nLet's see how tough you are again later on. Being tough is all about consistency!", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72720] = { id = 72720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arena Calls", description = "You ever been to the arena? Now there's a tough place! \n\nShow me how tough you are by winning some battles in the arena. \n\nMe? I've done plenty of fighting. I just enjoy lifting now and breaking some records.", progress = "Stay tough in the arena!", completion = "Keep it up! Remember, being tough is all about consistency.", objectives = "Win 10 Arena Skirmish battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72721] = { id = 72721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Very Best", description = "Have you seen those adventurers who train up those little creatures to fight each other?\n\nNow that's tough! You have to make those little creatures a little stronger each day.\n\nShow me how tough you are by defeating those other adventurers and their group of creatures!", completion = "You and your team look way tougher than before! \n\nCan you keep it up? Let's find out next time!", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72722] = { id = 72722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of War", description = "There's tough and then there's really tough.\n\nThink you can delve into some of the most dangerous places around and survive?", progress = "Show me some real higher level tough!", completion = "You look tougher than before, good work!\n\nDon't get complacent. Being tough is all about consistency, keep it up!", objectives = "Complete 4 dungeons on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72723] = { id = 72723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Battle", description = "You think you know tough? I thought I did too until I read about these massive challenges that are out there!\n\nSwarms of adventurers fighting each other over and over again. \n\nNothing is tougher than going against the odds, especially when it comes to things like flags!\n\nShow me just how tough you are!", progress = "If you get the flag, don't let it go! That's what I heard at least. Or was it let it go as soon as possible...", completion = "You look tougher than ever. I hope you stood out in the large crowds you were in, I know I tend to!", objectives = "Win 4 Battleground matches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72724] = { id = 72724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Savage Path Through Time", description = "You know what's tough? Time travel! You know what's even tougher? Fighting monsters while time traveling!\n\nShow me how tough you are by doing both.", progress = "Imaging all the reps I could do if I could time travel!", completion = "You're looking tougher already. Remember, being tough is about staying consistent. \n\nLet's see what you can do next time!", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72725] = { id = 72725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shrouded Path Through Time", description = "I've heard stories from the Dragonscale Expedition about a place called Pandaria. \n\nNow that sounds like a tough place! \n\nThink you're tougher than that? Show me!", progress = "Don't get confused by any mists or shrouds! At least that's what I've been told.", completion = "You're back! Think you're tougher now? We'll see next week, keep it up.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72726] = { id = 72726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frozen Path Through Time", description = "The Lich King! Ever heard of him? Me neither until a little while ago. I'm learning a lot these days.\n\nYou know what's tough? Learning new things and expanding your horizons.\n\nYou know what's just as tough? Facing down the threats from this Lich King! \n\nI honestly don't know how you're going to show me how you're tougher than that, but give it a shot.", progress = "I heard there was more than one Lich King. Did you all get a third?", completion = "You look a little chilly! Something tells me you're tougher than before.", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72727] = { id = 72727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burning Path Through Time", description = "Some gnome researcher told me all about this thing called a Dark Portal. Now that sounds tough! \n\nShow me you're tougher than all the things that happened around this Dark Portal!", progress = "How big is this Dark Portal really?", completion = "You look tougher! I'm going to assume you did what I asked.\n\nKeep up the good work!", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72728] = { id = 72728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Awaits", description = "You know what's a sure sign of toughness? Helping out the community in the Dragon Isles! \n\nThere's plenty of problems to solve here. Show me how tough you are by helping out!", progress = "You know you're tough when you're helping out your community.", completion = "I heard about all the things you did! If that's not tough, I don't know what is.\n\nKeep up the pace.", objectives = "Complete 10 World Quests in the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72729] = { id = 72729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Swog", description = "A peculiar coin fished up around the Dragon Isles.\n\nYou've heard rumors from fellow anglers of a creature in the Ohn'ahran Plains who collects such things.", completion = "<The Great Swog regards you.>", objectives = "Bring the Rusted Coin of the Isles to The Great Swog in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72734] = { id = 72734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apex Canopy River Run - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72735] = { id = 72735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Into Perfume", description = "I just got the best smelling perfume while in Stormwind! Hey, {name}, you should get some for yourself! Oh, and maybe check out this Inspector Snip Snagglebolt I ran into. He asked me to send any new customers his way first. I can't imagine why, but maybe you should see what he's up to.", completion = "Hey, you haven't already bought any of that perfume, have you? I've got some intel you might just want to hear first.", objectives = "Report to Inspector Snip Snagglebolt in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
