quests[72773] = { id = 72773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning Ingenuity", description = "There are some goblins within Valdrakken that are investigating an abandoned titan device. \n\nHonestly, they're causing quite a disturbance. Some are concerned their investigation could cause more harm than good.\n\nThe denizens of Valdrakken would appreciate you meeting these goblins to see if you can find a solution to their investigation.\n\nWithout destroying part of our city.", completion = "Nice to meetcha. We could use another pair of hands figuring out how to kickstart this thing.", objectives = "Meet Greyzik Cobblefinger within Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72783] = { id = 72783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders", description = "That's a nifty thing you got there from the titan device. Now hand it over!\n\nJust kiddin'! I wouldn't know the first thing about how to use that. Do you?\n\nGo talk to Mimzy Sprazzlerock. She's got a whole gig setup findin' folks to do something called \"crafting orders\".\n\nYou put up the goods, someone takes 'em and crafts something for you. \n\nSimple, right? Go talk to Mimzy to check it out! And don't tell her I sent you.", completion = "<You can return to any Crafting Order representative to put in more orders for new equipment as long as you have the components!>", objectives = "Speak with Head Clerk Mimzy Sprazzlerock to learn about Crafting Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72784] = { id = 72784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supporting the Cobalt Assembly", description = "{name}, excellent timing.\n\nHave you heard of the Cobalt Assembly? It was once a wondrous place where most of my kin lived.\n\nThe Sundered Flame forced us out and have taken it over. \n\nThere was a hope that we could take it from them, but the latest information from there shows we are fighting a losing battle.\n\nCan you lend us your support? Meet Venthi within the Cobalt Assembly if you can.", completion = "We could always use more aid. Allow me to tell you of our current situation.", objectives = "Speak with Venthi within the Cobalt Assembly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72785] = { id = 72785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contribute Supplies: Draconium Nugget", progress = "I'm always glad to collect rare materials for better fishing gear.\n\nIf your nets are good enough already, bring me any spare draconium nuggets you find.", completion = "That is a heavy one! Thank you, my friend." }
quests[72786] = { id = 72786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contribute Supplies: Strong Seavine", progress = "I'm always glad to collect rare materials for better fishing gear.\n\nIf your harpoon rope is good enough already, bring me any spare strong seavine you find.", completion = "Strong enough, is it? Thank you, my friend." }
quests[72787] = { id = 72787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contribute Supplies: Battered Imbu-made Net", progress = "I'm always glad to collect rare materials for better fishing gear.\n\nIf your nets are good enough already, bring me any spare Imbu-made nets you find.", completion = "A fine knot you have found. Thank you, my friend." }
quests[72788] = { id = 72788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contribute Supplies: Irontree Branch", progress = "I'm always glad to collect rare materials for better fishing gear.\n\nIf your harpoon is good enough already, bring me any spare irontree branches you find.", completion = "A good, solid branch. Thank you, my friend." }
quests[72789] = { id = 72789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contribute Supplies: Salinated Serevite", progress = "I'm always glad to collect rare materials for better fishing gear.\n\nIf your harpoon head is good enough already, bring me any spare salinated serevite pieces you find.", completion = "Be careful, it's razor-sharp. Thank you, my friend." }
