quests[72798] = { id = 72798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tale of the Phoenix", progress = "The phoenix knows there is no shame in death.\n\nShame falls only on those who flee the challenge.", completion = "The defeated phoenix rises evermore to continue to fight.\n\nWatch it. Learn from it.\n\nBe better than it." }
