quests[72809] = { id = 72809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insert Coin", progress = "The Warcraft Rumble game machine stands before you.\n\nDo you dare play?", completion = "You did great!" }
quests[72810] = { id = 72810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shattered Path Through Time", description = "I've been reading some books about this cataclysm that happened to Azeroth.\n\nYou know what's tough? Seeing places you were used to get destroyed by a dragon.\n\nYou know what's even tougher? Fighting in those places and surviving!", progress = "Good thing the Dragon Isles didn't get hit by this cataclysm.", completion = "You're looking tougher already!\n\nLet's see how tough you are next time we talk. Remember, being tough is all about consistency!", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
