quests[72821] = { id = 72821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands (60) E" }
quests[72831] = { id = 72831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creative Solutions", description = "I have always hoped that mages would once again walk the streets of Theramore. This, however, is not what I had in mind.\n\nIf this Sullied Banner truly intends to reconstruct a working mana bomb, then they must be stopped--but I will not repeat the mistakes Malygos made. There must be a way to reason with them. \n\nI shall place an enchantment upon you that will allow you to subdue the mages without killing them. See to it that they cannot continue their ill-intended actions.", progress = "These mages walk a dangerous path, but I do not believe that they are beyond redemption.", completion = "Arcane magic has always been well-suited to matters of stasis and security. I am pleased that we could put it to such effect here.\n\nStill, the question remains: what drove these mages to such reckless action in the first place?", objectives = "Pacify the rogue mages of the Sullied Banner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72832] = { id = 72832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aftershocks", description = "These precocious whelps seem to be trying to recreate the very bomb that leveled Theramore. Predictably, they have yet to succeed. Still, I would rather not give them the chance to stumble into a more effective solution.\n\nIf our dear Aspect wishes to avoid simply turning the whole lot of them into mana dust, then I suppose I can refrain from carpeting the ruin in spellfrost. Someone will need to go and repossess their banal attempts at ordinance, though.\n\nDo take care not to set them off, hmm?", progress = "Do not dally, mortal. Those bombs may be prototypes, but even an accidental detonation could present issues.", completion = "Well, {class}, I suppose you are not as hapless as most mortals who cross my path. You may deserve some modicum of recognition for your deft work.\n\n...not from me, mind you. If you want a pat on the head, go ask Kalecgos.", objectives = "Teleport eight Prototype Mana Bombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72833] = { id = 72833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Cycle", description = "With many of their rank-and-file captured, it is time to deal with the leader of this so-called Sullied Banner.\n\nI imagine Kalecgos wishes to take her alive. I have no such compunctions, but I am not a picky dragon. So long as we put a stop to her schemes, I care little what happens to her.\n\nHis plan, though troublesome, seems to have worked thus far. I am willing to give him the benefit of the doubt, at least for a short while longer.", progress = "Act quickly, {class}. I do not want this gnome to slip away from us now.", completion = "I admit, I did not expect things to go this way. That gnome... no. Magus Flickerflame. She has suffered much. It makes sense that she would wish to cultivate her power, in order to subvert further tragedies from coming to pass.\n\nKalecgos says that we must be mediators and protectors, not hoarders of secrets. I think I am beginning to understand what he means.", objectives = "Apprehend Turi Flickerflame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72854] = { id = 72854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Enemies Abound", description = "Just when we get our feet back under ourselves, someone wants to knock us down again.\n\nThere are people who still think that we don't deserve this home, and they're willing to kill us to get what they want.\n\nAnd some old grudges never go away. Somehow, the Scarlet Crusade, or what remains of it, has gotten a toehold on Fenris Isle.\n\nGo to the southern wall of the Ruins of Lordaeron. Deathstalker Commander Belmont has got eyes on them.", progress = "This is why we can never let down our guard.", completion = "I didn't expect the Scarlets to have so many soldiers they could muster for an attack like this.\n\nIf I wasn't so mad I'd be impressed. Fortunately when I get mad, I get stabby.\n\nStill, this is bad, {name}. This isn't just some random rabble of farmers. Someone must be calling the shots and they know what they're doing.", objectives = "Speak to Deathstalker Commander Belmont at the southern wall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72855] = { id = 72855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Sepulcher", description = "Faranell and Velonara already went to the Sepulcher to work on a piece of our plan.\n\nWe can hold the wall for now with just a few deathguards and dark rangers, but we need someone who can hit the Scarlets where they are. Preferably without losing more of our own.\n\nGo to the Sepulcher and meet with Velonara. You are the sharpened tip of our poisoned blade.", completion = "Good, you've arrived in one piece. Master Apothecary Faranell and I have pondered on a few ideas for how we can take out those Scarlets. \n\nBut first, we need to watch our backs out here. And I think Faranell is cooking up something rather explosive.", objectives = "Meet Dark Ranger Velonara in the Sepulcher in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72856] = { id = 72856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Like the Classic", description = "We of the Royal Apothecaries have synthesized many nuanced plagues in recent years, in keeping with our agreement with the Desolate Council not to... overdo it.\n\nBut when it comes to rooting out Scarlet assailants, there really is nothing like the classic. The original plague that exists -- mostly -- only in the diseased tissue of surviving descendants.\n\nGo, gather up samples from this marvelous wildlife and bring them to me. I can put them to greater use.", progress = "I remember the days when we had unfettered license to experiment and brew as we wished... ah, perhaps one day again. Have you found those plague samples?", completion = "Excellent! Ah, I can still smell that original plague formula. It brings back such pleasant memories. \n\nToxifying the ambient air, melting the living down to their bones, how I miss those days - err - did I say that out loud?", objectives = "Collect 12 Plagued Flesh from nearby wildlife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72857] = { id = 72857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom Weed", description = "You've heard of Gloom Weed, you've heard of Doom Weed, now it's time for... Boom Weed!\n\nThat's right, another variety grows right here in Silverpine! And it can be used in combination with our alchemical formulas for a very incendiary outcome.\n\nGo and collect some for me. Just mind your eyebrows. You don't really need any eyebrows, do you?", progress = "Have you found all the Boom Weed I need? I cannot wait to mix this up.", completion = "Wonderful! And I see you still have your eyebrows. I think. I'm sure you can get some new ones stitched on if you really want to.\n\nNow, let us commence with the alchemy!", objectives = "Collect 6 Boom Weed in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72858] = { id = 72858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acid Beats Paper", description = "While the Scarlet Crusade have taken Fenris Isle, they try to intimidate and cow our people in Silverpine Forest. \n\nWe cannot let them win either by strength or by terror. \n\nWhen you collect materials for Faranell's concoction, destroy any slanderous propaganda you find.", completion = "Words have power. Power that can be taken away, when the words are also taken away.\n\nOur people have suffered enough by ink and blade.", objectives = "Use the Acid Rifle to destroy Notices to All Undead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72859] = { id = 72859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Disguise", description = "Our plan is to send you to Fenris Isle, but first, you must look the part.\n\nWe've scouted out a group of Scarlet solders training in Valgan's Field, supervised by a lieutenant. That lieutenant's armor should let you walk deep behind enemy lines, unnoticed.\n\nTake it from them, however you see fit. I don't need to know how.", progress = "Have you acquired your Scarlet disguise?", completion = "That's one Scarlet officer that can't cause more trouble for the Forsaken, and now you can look the part.\n\nNext, let's hope that we can get you on that island without any fuss.", objectives = "Slay Lieutenant Hawlsey at Valgan's Field and take their armor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72860] = { id = 72860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear is Our Weapon", description = "The Scarlet Crusade is recruiting. Apparently, when you want to blame all your problems on someone else, people flock to the lies.\n\nBut that's a choice that they're going to live to regret. We're not the problem here. THEY attacked OUR home.\n\nTake one of the banshees with you. Between the two of you, those recruits will be scared to death.", progress = "Have you thinned out those Scarlet recruits?", completion = "It's better to kill something dangerous before it spreads. Now Fenris Isle is on its own, and not getting fresh blood.\n\nIt's time for the next phase of our plan.", objectives = "Frighten Scarlet Recruits and slay them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72861] = { id = 72861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Spy", description = "Now it's time to sneak you onto Fenris Isle. I know this armor isn't exactly what you want to wear, but it will help you move around without being noticed.\n\nApproach the isle on their level. No fancy sky maneuvers.\n\nOnce you've put on the armor, find a way to get across the water. There's a quartermaster who can tell you where to go from there.\n\nFrom there, you know how to raise bedlam.", completion = "Hawlsey! You're looking a bit grey around the gills.\n\nAre those new recruits working you to the bone already?", objectives = "Don your disguise and report to the Quartermaster Newlem on Fenris Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72862] = { id = 72862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among Us", description = "We could use those recruits to bolster us, but those dreadful undead are harrying our supply lines! They will all be put in the ground permanently, soon enough.\n\nCould you check on our stockpiles to make sure we've got enough for your recruits? Of course the good stuff has already gone up to Fenris Keep for the Commander, but everyone has to eat.\n\nWell, almost everyone.\n\nGet a move on, lieutenant.", completion = "I can smell the plague... and the smoke. \n\nWell done, cutting through their defenses.", objectives = "Plant Explosive Plague and eliminate Scarlet Archmages without being discovered.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72863] = { id = 72863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flight of the Banshee", description = "With the island's defenses weakened and the cannons and mages silenced, we're ready to safely bring in our troops once more.\n\nYou didn't think you would have to fight all of them by yourself, did you? \n\nI know you could, but leave some for the rest of us, too.\n\nWhen you're ready to call the others in, let me know.", completion = "They thought we would stay in our walls and hide? \n\nChildish pretenders. Now we'll show them the might of the Forsaken.", objectives = "Speak to Velonara to call in the full force of the Forsaken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72864] = { id = 72864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Living", description = "Now it's time for them to pay. They'll wish they never set foot in our lands and threatened our home.\n\nWe will drive them out, we will drive them into the ground, and we will leave them to rot.", completion = "Sometimes, the only way to get through to people is in the language they understand.\n\nAnd the Scarlet Crusade hears strength.\n\nBut those are just the followers. We need to reach the leaders of this brazen invasion and deliver the message, too.", objectives = "Kill every Scarlet that has a beating heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72865] = { id = 72865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This is the Hour of the Forsaken", description = "We haven't seen the Scarlet Crusade put this many fresh soldiers on the field in a long time.\n\nAnd we know that they didn't get here on their own. Someone's guiding them. Someone who's fought Forsaken before.\n\nSomeone I remember well.\n\nCome with me, and let's put an end to Commander Forsythe.", completion = "There, it's done. A few Scarlets may have escaped from us, but we've wiped them off of Fenris Isle. \n\nWithout their commander, hopefully they can't regroup anytime soon. And they'll think twice about coming after the Forsaken again.\n\nWe have our strength, our common purpose. And we have you.", objectives = "Slay Scarlet Commander Forsythe in Fenris Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72866] = { id = 72866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Lordaeron", description = "Let's get back behind the walls and meet the others. I think Belmont had the time of his unlife with you, getting to cut down Scarlets again.\n\nBut this isn't the end of the Crusade. Even though they lost, they might still turn this into yet another way to recruit.\n\nWe'll be ready if they ever come for us again. Or our neighbors.\n\nCome on, let's get back to the Ruins of Lordaeron.", completion = "Welcome home.\n\nWe couldn't have won this without you, I hope you know.", objectives = "Take the portal to return to the Ruins of Lordaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72867] = { id = 72867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am Forsaken", description = "We have fought to win back our home. We have fought to keep it safe. \n\nYour courage and strength are inspirational to the Forsaken. And with you, we know we have our champion. \n\nGo, they want to see you.", progress = "Go on, everyone's waiting to honor you.", completion = "See?\n\nAnd we will continue to fight, for as long as our bones let us, for our right and space to exist on Azeroth.\n\nWe are the Forsaken.", objectives = "Receive the honor and accolades of the Forsaken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72868] = { id = 72868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Hunting Trophies", progress = "What have you brought me, outsider?", completion = "Only the greatest of hunters can boast of this many great hunting trophies. You honor our hunt." }
quests[72869] = { id = 72869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Hunting Trophies", progress = "What have you brought me, outsider?", completion = "Only the greatest of hunters can boast of this many great hunting trophies. You honor our hunt." }
quests[72872] = { id = 72872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Deep", description = "Have you seen these deepflayers before? Well, of course you have! You were almost eaten by one!\n\nThey're getting a little too cozy to me and my people's settlement nearby, and need to be dealt with. Inside the cave, outside the cave, they're all over the place!  That's why I came here in the first place.\n\nSince I can tell we'll be ramblin' round with each other for a bit, why not give me a hand?", progress = "Not bad, uplander! Have you dabbled in monster hunting before this?", completion = "Did you made friends with any of the flayers?\n\nHah! Just kidding! That was a joke! Please don't try to do that unless you want become some swooper's tasty snack!", objectives = "Kill 8 Deepflayers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72873] = { id = 72873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Was Not Enough", description = "You're smellin' real down and out there, kid. Can't imagine what you been through to end up here.\n\nWell, it don't matter! We niffen ain't the sort to leave anyone behind. Especially not people who're about to be served up as a deepflayer's snack!\n\nThis master sniffin' snout of mine can smell you didn't come down here to our Zaralek Cavern alone. What say we get you out of those crystals and find your friends!", completion = "Told you we'd sniff out your companions! \n\nThough it seems like they're carrying a lot of dirt on their backs. The figurative kind, I mean.  \n\nAnyway! If you're willing to pay back the favor of me rescuing you, I've still got some business here.", objectives = "Follow Elder Honeypelt to find Wrathion and Sabellian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72874] = { id = 72874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets From Our Father", description = "Look closely, {name}. You see this odd chunk of metal in the deepflayer muck?\n\nI have felt my head swimming since we arrived in these caverns. I thought it was just the ceaseless prattling of our whelp, Wrathion, but this object here may prove otherwise.\n\nI will continue my efforts to unlock this relic's secrets. Seek out similar pieces in the nearby caves. A dark theory is emerging, though we will need more information before I am willing to confirm it.", progress = "I know this device still has power...", completion = "A dead scout for the Sundered Flame near one of the relics? \n\nThat is no coincidence. Ebyssian told us they were pursuing clues left by father. I must admit that this relic, and the ones you describe finding, look quite familiar to me.\n\nFamiliar... And familial. It stirs my insides.", objectives = "Investigate the scavenged relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72875] = { id = 72875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", objectives = "Greetings adventurer. Please, take these supplies to aid you in your efforts to help our community!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72876] = { id = 72876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Multiple Dragon Isles Artifacts", progress = "Do you have something for the archives?", completion = "Look at all these artifacts! This might take a minute. \n\n<Cataloger Jakes hastily makes several notes in her ledger.> \n\nGot it! Off with you, now! Come back if you have more!" }
quests[72877] = { id = 72877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Multiple Dragon Isles Artifacts", progress = "Do you have something for the archives?", completion = "Look at all these artifacts! This might take a minute. \n\n<Cataloger Jakes hastily makes several notes in her ledger.> \n\nGot it! Off with you, now! Come back if you have more!" }
quests[72878] = { id = 72878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slime Time Live", progress = "Snail slime is the base that most of our incense is built upon.", completion = "Did Aurantia send you? This snail slime is mighty fine--it'll make some great incense!", objectives = "Lasso 8 Dripping Redolent Whelks to collect Snail Slime in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72879] = { id = 72879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smells like Kith Spirit", description = "Well, it's not too often we see uplanders around here!\n\nHoneypelt must have a good reason for sending you my way, she doesn't trust just anyone with her incense.\n\nA kith's incense is their pride and joy. Each one smells unique, and we use them to identify each other. \n\nMaking incense is a delicate business. Just head over to that cauldron and Marie Shellie and I will help ya out with whipping up some replacements.", progress = "It's starting to smell really good!", completion = "Not bad for your first go at it! You should go put these down where they belong.", objectives = "Make Niffen Incense with Citros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72880] = { id = 72880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incense Gratification", description = "That's some real potent incense you made! Usually it takes time to get this good!\n\nNow, I've got some of my own brewing to do, so you're gonna have to go out and set those up by yourself.\n\nOnce you're finished I'm sure Honeypelt will be mighty keen on hearing about it! Best follow up with her when you're done.", completion = "Thank you, {name}! I take it Citros was helpful?", objectives = "Place 9 Missing Incense in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72881] = { id = 72881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Swallow's Tale", description = "Uplander!\n\nI'm Effervesta, Lady Redolence to the niffen of Loamm--the daughter of their leader. No need for formalities though, you can just call me Effie!\n\nKeep this between you and me, but we're a bit behind on some shipments to Glimmerogg, and the Drogbar are definitely not happy one bit! You've already been so helpful to Elder Honeypelt... maybe you can give me a hand too?\n\nOur swallows keeper, Nevroll, might be able to dig up some dirt on the issue. \n\nWill you go talk to him, please?", completion = "Really? You'll help?", objectives = "Speak with Swallows Keeper Nevroll in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72882] = { id = 72882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flown the Coop", description = "They're gone! Just... gone!\n\nThe swallows, Nevroll, all of it!\n\nAnd now you say that Effervesta told you that we're behind on our shipment of swallow nests to the Drogbar?\n\nThis is really bad, Uplander. \n\nIf you want to help, you can start by bringing back as many birds as you can find.\n\nI'll see if I can scrape together any useable nests for the Drogbar in the meantime.", progress = "If Nevroll or the Drogbar show up before we find those birds, we're toast!", completion = "Oh, I'm so glad you were able to find some of them!", objectives = "Find 6 Lost Swallows in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72883] = { id = 72883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bitter Pill to Swallow", description = "<The corpse of a single cave swallow rests on the cavern floor. You should tell Cinnam.>", progress = "Oh no...", completion = "Who cares about dead swallows now? Effie is missing!", objectives = "Take the dead swallow to Cinnam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72884] = { id = 72884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Effervesta", completion = "Look, there's a cave up ahead! That must be where she is.", objectives = "Search for clues about Effervesta's whereabouts in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72886] = { id = 72886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suss Out the Imposter", completion = "Effie! I'm so glad she's okay!", objectives = "Defeat Nevroll and rescue Effervesta in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72888] = { id = 72888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
