quests[72899] = { id = 72899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 2/8" }
quests[72900] = { id = 72900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper of the Ossuary", description = "Greetings, {name}. While I continue to search for the remaining blue dragons, I could use your aid in another matter.\n\nAlexstrasza and I plan on laying to rest the remaining essences of Malygos and Sindragosa. She has held on to their lingering essences after both were slain years ago.\n\nSenegos said there was a time where dragons would be laid to rest in the Veiled Ossuary. Unfortunately, the place is a mess.\n\nHe's gone ahead to clean the area up with Stellagosa. Could you aid them?", progress = "Ah, here to help are we?", completion = "Shall we begin?", objectives = "Meet Senegos in the Veiled Ossuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72908] = { id = 72908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sight Beyond Sight", description = "I had not expected to find djaradin here, though it does not surprise me. Legends tell of their elders slumbering beneath the earth. It makes sense that some would delve underground in search of them.\n\nTheir forces are heavily guarding this outer area. I recognize the magic their scouts are using--it is farsight, powered by those totems near them.\n\nI spotted a larger totem at the top of the nearby tower. If you can figure out how to power it, we can use it to search the caldera from afar.", progress = "This tower provides the best vantage point in the caldera.\n\nIf there is any evidence that Fyrakk came through here--or worse--we will see it.", completion = "<Ebyssian narrows his eyes in contemplation. At last, he sighs a deep breath and sets his jaw.>\n\nWe cannot act yet. We need more information, and a better opening.", objectives = "Inspect nearby Flamesight Totems to find a way to activate the Greater Flamesight Totem atop the guard tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72909] = { id = 72909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legends of the Zaqali", description = "Because of our recent conflicts, I have been researching the djaradin. Our archives had little information on their elders.\n\nLegends say that they were once great warlords who now slumber beneath the earth. The djaradin believe they will awaken and lead them to a brutal victory against the dragonflights.\n\nWe need to know what we are up against. There is an empty shrine just below us that resembles the ones housing the elders. \n\nWe may find some answers there.", completion = "From what we have gathered so far, it seems that Iridikron has made a deal with the Zaqali and sent the Primalists to awaken their elders.\n\nDo they merely share a common enemy, or is Iridikron receiving something else in return?", objectives = "Inspect the Zaqali belongings left near the Elder's shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72910] = { id = 72910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Thy Enemy", description = "That djaradin called her people the \"Zaqali\"--but my troops did not report any information regarding a second active djaradin tribe in the Dragon Isles. I detest an unknown in war.\n\nWe will need to learn what we can about them--and quickly--in order to assess their strengths and weaknesses. I have found the best way to know a culture is to examine how they make war.\n\nSlay any you find in the nearby area and take their armaments. I will expect your report.", progress = "No detail about an enemy is insignificant. Everything can be used against them.", completion = "These Zaqali are far more magically talented than the Qalashi, it seems.\n\nBothersome.\n\nThe beast we knew would have been preferable to the beast we do not, but I will adapt our strategies accordingly.", objectives = "Gather 8 pieces of Zaqali equipment from Zaqali djaradin near the empty shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72911] = { id = 72911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Out the Head", description = "While you and Ebyssian were away, I had an epiphany.\n\nThat corrupted caldera is at the center of the Zaqali elder's slumbering prison and their war camps. Whatever is located within is the key to what the Primalists are planning.\n\nIt is lightly guarded as well. Only a Primalist and a Zaqali priest. If we take them out, we can discover what I believe will be the truth behind all of this.", completion = "<Ebyssian looks between Sabellian and the caldera, his breath unsteady.>\n\nWhat... What has Fyrakk done?", objectives = "Kill Shrinekeeper Qanosh and Earthrender Ku'siva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72912] = { id = 72912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consequences", description = "Shadowflame...\n\nDid Iridikron know this was here? Did he corrupt his brother? Or has Fyrakk fallen to the temptation?\n\nOnly ignorance or arrogance tempts fools to seek it out, believing they can master dark forces that not even Neltharion could. It infected him, slowly, like a gangrenous lesion until finally he succumbed to madness.\n\nSo too will Fyrakk.\n\nI will not take that risk with Sabellian. \n\nHe was burned badly before I was able to fly you to safety. Let us assess the extent of the damage.", progress = "I will not lose a single person to shadowflame.\n\nNot Sabellian. Not anyone.", completion = "If Fyrakk is absorbing the shadowflame infused in the caldera itself, we will need more strength than just our own to stop him.\n\nBut we cannot worry about any of that until Sabellian's wound is cleansed of corruption.", objectives = "Inspect Sabellian's injuries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72913] = { id = 72913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield Triage", description = "Our situation is less than ideal, we will have to improvise. I can conduct flame to earth to create magma. Shadowflame could behave similarly.\n\nThe Primalists are summoning earth elementals nearby. If we extract their cores, I can use them to contain the shadowflame infecting Sabellian's burn.\n\nThe Zaqali's totems should already be attuned to the elements here. It will make the siphoning process much more efficient.\n\nSabellian will need to come with us. I must keep an eye on him--for his sake.", progress = "We cannot delay. Shadowflame deteriorates both mind and body with insidious haste.\n\nI will do everything I can to halt it.", completion = "I can only hope these components will be sufficient for the cleansing ritual.", objectives = "Collect 5 Vacant Elemental Cores and 1 Zaqali Flame Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72914] = { id = 72914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rushing Quality", description = "Look ahead! The djaradin have cleared away from the northeastern side of the caldera to augment their forces near the elders.\n\nThere is an altar bordering the lava pool that appears safe for now. We can set up our spell components there.\n\nLet us hurry before the djaradin return.", progress = "Fyrakk and the elders can wait.\n\nIf Sabellian is lost, we will fail regardless.", completion = "Sabellian is still injured from the burn, but the shadowflame has been purged from him.\n\nIt is the best I can do for now. I will ensure that he has time to rest later.", objectives = "Cleanse the shadowflame from Sabellian's injury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72915] = { id = 72915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance of Convenience", description = "The Primalists have a sizeable force of djaradin guarding them while they complete their work.\n\nEven in small numbers, djaradin prove to be formidable opponents when allowed to engage in battle on their own terms. It is far better to bring the fight to them, leaving as little time to react as possible.\n\nTake them out. We cannot have them encroaching on the space we have managed to carve out thus far.", progress = "I am certain there will be no lack of djaradin this close to the elders' shrines.", completion = "Good. We will need to keep this area clear for now.", objectives = "Kill 4 Zaqali djaradin guarding Igira's shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72916] = { id = 72916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shut Them Down", description = "Up ahead, the Primalists are working to awaken the Zaqali's final elder.\n\nWhen we used the farsight totem earlier, I observed that they were draining something from the elder. Now I realize it is likely an attempt to dispel the magic keeping the elder in stasis. They are using elemental cores to contain the magic in the same way we did to cleanse Sabellian.\n\nFyrakk absorbing shadowflame is disastrous. We cannot add an elder awakening to that threat. We must halt their efforts.", progress = "I cannot be certain if this will stop them entirely, but it will at least slow their progress.", completion = "I hope we have bought ourselves enough time to gather reinforcements.", objectives = "Destroy 3 Earthdrainer Conduits and 4 Extracted Elemental Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72917] = { id = 72917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Hell's Heart", description = "No longer can we allow Fyrakk to lie here peacefully, twisting himself with shadowflame and becoming a threat on par with Deathwing. We must act! Is it dangerous? Yes. But not to do anything would be catastrophic.\n\nI have ripped gronn apart with my bare claws before. Those battles were gambles, this one is not. Slaying a proto-dragon with a weapon meant for dragonslaying is obvious. It is logical. It is guaranteed.\n\nI will not tremble before an opportunity to end this now.", completion = "We... were no match...", objectives = "Help Sabellian slay Fyrakk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72918] = { id = 72918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Dragon Left Behind", description = "I... cannot move so long as this spear remains in my side. But we need to follow Fyrakk's trail.\n\n<Ebyssian grunts sharply, his breathing labored, claws digging into the dirt.>\n\nRemove it. I can... bear the pain it will cause.", progress = "He did not leave me.\n\nI cannot leave him.", completion = "We should both be able to walk.\n\nFyrakk has left a trail of destruction across the cavern. We must help any harmed by him, even if we can do nothing to stop him.", objectives = "Find a way to remove the spear from Ebyssian's side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72919] = { id = 72919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raked Over the Coals", description = "The shadowflame has already corrupted Fyrakk irreparably. Every place in Zaralek darkened by his wings has been lit ablaze with shadowflame.\n\nWe cannot leave it behind and let it fester--it will need to be extinguished while it is still kindling, lest we allow its corruption to take root.\n\n<Ebyssian coughs, then winces.>\n\nSabellian and I cannot take to the air in this state. Disperse the flames with your drake. We will follow you below and meet you back at Loamm.", completion = "Titans forgive us...\n\nThere will be worse than this to come.", objectives = "Disperse 12 patches of shadowflame by dragonriding through them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72920] = { id = 72920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Burning Sky", description = "Fyrakk must have breathed shadowflame upon the niffen on his way out of the cavern. There is too much fire for it to have merely sloughed off of him.\n\nHe did this on purpose.\n\n<Ebyssian clenches his staff tightly. He looks weary for a moment. Only a moment.>\n\nWe will save Loamm. All of Loamm. No more lives will be lost.", completion = "<Ebyssian struggles to catch his breath, wiping the sweat from his brow.>\n\nFyrakk will answer for this.\n\nI swear.", objectives = "Extinguish the fires consuming Loamm and rescue 5 Loamm villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72921] = { id = 72921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Trail Again", description = "Ah... the Veiled Ossuary. I was given the task to be a sort of gravekeeper, which included keeping wildlife away from the area.\n\nI had a rather fun spell split up within several tomes kept within this place to deal with such pests. \n\nThe other blue dragons did not approve of my... reckless methods, so I had to keep the tomes hidden.\n\nHere, allow me to cast a spell on you to grant you the sight to find these old tomes.\n\nOnce they are all gathered, we can cleanse this place of the invasive wildlife.", progress = "Did you find my old tomes?", completion = "Here they are! I am glad some things have survived all of this time.", objectives = "Receive Senegos's special sight, then recover the missing tomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72922] = { id = 72922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fading Embers", description = "This is a difficult situation, my friend. Wounds and insecurities cannot be easily dismissed. Only time--and cooperation--can soothe the sting born of longstanding rivalries.\n\nBut there are more urgent matters to address. If there is a large force of drakonids still loyal to the memory of Neltharion, this land is much more dangerous than any of us expected.\n\nEmberthal still pursues Sarkareth--alone. She must be made aware of the threats that surround her. We must find her and give her aid.", completion = "Sarkareth may try to hide behind the might of Aberrus but to no avail.", objectives = "Help Emberthal stop Sarkareth at the Brimstone Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72923] = { id = 72923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Whisper to Sabellian", description = "Our assault on Brimstone Garrison will not work without Sabellian and his relentless and mighty dragons. We must convince him that our objectives are aligned.\n\nIf we appeal to him as a tactician and general, I'm sure he will help us... I hope.\n\nWe will find him with his troops at the Djaradin Assault.", completion = "Perhaps we will be able to fight as one.", objectives = "Speak to Sabellian at the Djaradin Assault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72924] = { id = 72924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appealing to the Black Prince", description = "Our assault will not be successful without the stealth and cunning of Wrathion and his Blacktalon agents. We must convince him to help us.\n\nThankfully, I know in his heart he will not deny someone in need--especially if they flatter him.\n\nLet us go to Wrathion at the Obsidian Rest and try to sway him.", progress = "I only hope that his temper has cooled by now.", completion = "I am glad to have him by our side.", objectives = "Speak to Wrathion at the Obsidian Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72925] = { id = 72925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Our Powers Combined", description = "Emberthal is waiting for us in front of the Brimstone Garrison.\n\nCome, {name}. She will be pleased to see we have rallied the full might of the black dragonflight to aid her cause.", completion = "Nothing can stop the black dragonflight when we stand together.", objectives = "Speak to Emberthal at the Brimstone Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72926] = { id = 72926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Right Hands", description = "There are several weapons of historical value that I believed were lost to time. I would bet my talons that they are here at this garrison.\n\nThe dragonspawn and drakonid loyally cling to the memory of my long-dead father. Misguided fools. \n\nThey have access to my father's forges and weapons, and it is likely the very weapons I thought lost are stored nearby. \n\nIf they find out what they have, they will use the weapons against us. They cannot remain in their claws.", progress = "These fools must be parted with such powerful blades.", completion = "We make a great team, my friend!", objectives = "Retrieve the Ebon Eviscerator and the Resting Blade from the Brimstone Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72927] = { id = 72927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Sarkareth", description = "Now that we have a foothold within the garrison, we can extend our search. We will hold off the forces of Aberrus here while you find Emberthal and aid her in reaching Sarkareth. We will join you as soon as we secure the front here.", completion = "There he is.\n\nAberrus protects him still as he works on that device. There must be a way for us to strip his defenses!", objectives = "Meet Emberthal within the Aberrus Approach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72928] = { id = 72928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wipe Them Out", description = "Do you know what I see when I gaze upon the Brimstone Garrison?\n\nTraitors.\n\nThese soldiers believe themselves followers of the black dragonflight, yet they ignore us, the true heirs to Neltharion, and bend a knee to the specter of our malevolent father. \n\nThis cannot be allowed to stand. \n\nShow them the error of their ways.", progress = "I know that I rule with an iron claw... but it is only because I see what must be done to preserve our people.", completion = "It is a shame that these warriors swear allegiance to the wrong cause. They could have been fine allies, but their misguided allegiance doomed them.", objectives = "Defeat the Brimstone forces loyal to Neltharion in the Brimstone Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72929] = { id = 72929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracking His Shell", description = "We have seen shields like this before. Sarkareth is drawing on the power of Aberrus to protect himself while he finds his way in.\n\nCowardly, but clever.\n\nDisrupt the conduits that are supplying his shield power, and we should be able to reach him.", progress = "We must bring that shield down!", completion = "Good. Now I have one last chance to reason with him.", objectives = "Destroy the conduits generating the shield at the Aberrus Approach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72930] = { id = 72930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping Sarkareth", description = "This is our last chance, {name}. If we allow Sarkareth to slip in to Aberrus, he may gain power that puts him beyond our reach. We must stop him now!", completion = "He does not care for the dracthyr loyal to him. He only cares for himself.\n\n<Emberthal sets her jaw.>  \n\nHe is lost to us all now.", objectives = "Defeat the Dreadful Defender at the Aberrus Approach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72931] = { id = 72931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Camp", description = "Since Sarkareth now wields the power of Aberrus's defenses, he has an army that will shield him from us.\n\nThe next step for us will be to establish a stronghold inside the garrison. That way we can search it without interruption. \n\nMeet me there.", progress = "I have full faith we will carve a path through the garrison.", completion = "Good. Now we can safely support Emberthal in her search. I know she will succeed in stopping Sarkareth.", objectives = "Find Ebyssian in the Brimstone Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72933] = { id = 72933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolling Out", description = "I remember having so much fun rolling these creatures up with my spells. Unfortunately, I fear these old bones will not let me move as quickly as I once did.\n\nI would love for you to give it a shot. Let me live vicariously through you! \n\nThe more creatures you roll up, the bigger the ball becomes. The bigger the ball, the bigger the creature you can roll out.\n\nSpeak to me and I shall give you my special arcane ball to roll up the creatures around here.", completion = "Fine work! Ah, to be young again.", objectives = "Use Senegos's Arcane Ball to roll up the creatures lurking in the Veiled Ossuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72934] = { id = 72934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lest We Forget", description = "We will be joined shortly by Kalecgos and Alexstrasza. Before then, I have a request.\n\nThere was a tradition to have gravestones set before your death. It allowed you to choose where you would rest when you passed.\n\nIt was the job of the caretakers to update the gravestones and deposit the lingering essence of arcana at the site.\n\nBefore our guests join us, would you help me in this task? \n\nTake this list, and these graves. Update the existing graves and place the new ones.", completion = "Thank you, {name}. I believe we are prepared for our guests to arrive.", objectives = "Update the gravestones of the departed blue dragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72935] = { id = 72935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archives Return", description = "It is not unusual that Malygos and Sindragosa would have such powerful memories. From what I understand, their deaths were particularly painful. Both slain by adventurers.\n\nIt breaks my heart to think of Sindragosa enduring death not once, but twice after being raised by the Lich King.\n\nBut enough of this old dragon's ramblings. Stellagosa and I will meet you back at the Azure Archives.", completion = "Thank you for your help, {name}. As you can see, more blue dragons have arrived! \n\nYet... some are still missing. We cannot forget about them.\n\nI will also ensure we find out more information about this strange phenomenon with Malygos and Sindragosa's memories.", objectives = "Return to Kalecgos in the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72936] = { id = 72936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azuregos's Support", description = "Many blue dragons have returned, and many others have informed me of their plans to make their ways to the Isles.\n\nThere are a few key members of the flight, however, that I have not heard from. One of them may be able to help: Azuregos, stationed within the Nexus in Northrend. \n\nYou, myself, and Sindragosa will travel to meet Azuregos. He has ignored all of my attempts to contact him from afar.\n\nThanks to the oathstone being empowered, Sindragosa can now travel further than ever before.", completion = "Perhaps Kalecgos's timing is not as bad as I thought... especially if he has the simulacrum of Lady Sindragosa with him.", objectives = "Travel to the Nexus in Northrend to meet Azuregos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72937] = { id = 72937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unusual Disruptions", description = "Of course I can help track down the missing blue dragons. However, I have a mess on my hands that must be addressed first.\n\nMoments ago, several bursts of arcane energy swept through the Nexus, followed by attacks of strange arcane creations.\n\nI can create a method of tracking down the blue dragons if you can put down the locations of this wild arcana.\n\nTake this staff--do not break it--and use it on three locations within the Nexus. Oh, and prepare yourself for a fight.", progress = "Do you need even more help? Just place the the staff at the disruption.", completion = "Well... things appear much calmer now. \n\nI suppose I better investigate how \"wide spread\" these wild memories will become.", objectives = "Put down strange arcane attackers in the Nexus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72938] = { id = 72938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archival Arrival", description = "I have crafted a magical globe to help you find the remaining blue dragons. It should give you their rough locations.\n\nNow go. On top of everything else I was working on, I must now investigate these \"memories\" that attacked the Nexus.\n\nI shall get to the bottom of it.", completion = "Hopefully Azuregos will join us later. \n\nIn the meantime, we have the whole of Azeroth to search.", objectives = "Return to the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72939] = { id = 72939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theramore", description = "According to Azuregos's notes, the blue dragon Surigosa was last seen investigating a sect of rogue mages known as the Sullied Banner. \n\nSurigosa's last missive stated that she intended to travel to the ruins of Theramore. Perhaps she uncovered traces of the Sullied Banner there. Either way, if Surigosa is to be found, Theramore seems the best place to search for her.", completion = "Theramore? I would rather not return to that place... but if Surigosa is there, then perhaps there is work to be done.", objectives = "Speak to Kalecgos about Surigosa's last known location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72940] = { id = 72940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where in the World is a Lost Blue Dragon?", description = "Azuregos has narrowed down the locations of the missing blue dragons.\n\nEach of us will handle finding several of them. I would entrust you to aid us in finding a few others.\n\nChoose where you'd like to go first.", objectives = "Choose an area to investigate the missing blue dragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72941] = { id = 72941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancestral Advice", description = "I have a message for my descendent. It is very important.\n\nI understand you are new to our language. I will try to speak in small, (100)-easy words. When you are ready to give your full attention, I will (90)-share my message.", progress = "Did the ancestor give you a message?", completion = "Well, that's hopefully close enough.", objectives = "Listen to the ancestor's message and convey it accurately.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72942] = { id = 72942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veiled Trouble", description = "I was hoping that we would find a way to dispel these strange arcane memories from what remains of Malygos and Sindragosa.\n\nIt appears they've grown more out of control than I expected. \n\nPlease, accompany some of the gathered blue dragons to the Veiled Ossuary and help Azuregos.\n\nSindragosa and I will remain here, and investigate what to do about this situation.", completion = "I suppose this is that \"teamwork\" Kalecgos has been talking about. \n\nPerhaps this is useful after all.", objectives = "Investigate the arcane disturbances within the Veiled Ossuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72944] = { id = 72944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sending Stone: Protest", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", progress = "What have you found?", completion = "Well... this stone was unexpected.\n\nIt would seem this Adamanthia was not beyond reason.", objectives = "Find a Sending Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72945] = { id = 72945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Path Ahead", description = "I have a message for Chief Kranac Sagesnow. I believe that it is not too late to lead our people down a (80)-better path.\n\nHowever, if he chooses the wrong direction, I see only (90)-darkness ahead for our people. \n\nWhen you are ready, I will (80)-impart this message.", progress = "It would be best to not leave the chief waiting!", completion = "That the Winterpelt ancestors trusted you to give this message to their chief is an excellent sign.\n\nHow did he react?", objectives = "Listen to the ancestor's message and convey it accurately.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72946] = { id = 72946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veiled Ossuary Chaos", description = "Malygos and Sindragosa's essences have created this massive arcane disruption. Their memories are running around the Veiled Ossuary trying to drain the arcana out of the graves!\n\nOur combined efforts are merely keeping the energies at bay. We need the memories in the nearby area disrupted.\n\nOnce they are dispelled, we should be able to remove this barrier to reach the essences inside.", progress = "Hurry! We need to deplete the arcana in this area.", completion = "The barrier is getting weaker! Fine work.", objectives = "Weaken the arcane invader's control over the Veiled Ossuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72947] = { id = 72947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of Old", description = "Three incredibly powerful memories have formed throughout the Veiled Ossuary.\n\nSoon their energy will be so vast that they will be able to create their own arcane constructs... thus overwhelming this place.\n\nTake them down, so we can weaken this barrier and reach Malygos and Sindragosa's essences!", progress = "Have you handled those memories yet?", completion = "The chaos in the area is weakening. Tell me, what memories did you see?", objectives = "Slay three powerful memories within the Veiled Ossuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72948] = { id = 72948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Still Remains", description = "The barrier is weakening, thanks to your aid. In a moment it will be broken down.\n\nOur main priority is recovering Malygos and Sindragosa's essences. Something has gone very wrong with laying them to rest. There are a few theories I have regarding their current state. We can speak about it as we enter.\n\nLet me know when you are ready.", progress = "It seems the blue dragons still cannot leave behind our legacy.", completion = "To think a merciful gesture could turn like this...\n\nI suppose we all underestimated the rage still within Sindragosa and Malygos.", objectives = "Go beyond the arcane barrier to recover Malygos and Sindragosa's essences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72949] = { id = 72949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swiftly to the Archives", description = "I can hear the pained cries of rage and agony from these essences. I suspect this was triggered after attempting to put them to rest. \n\nThey were dormant for a time, but the combined rage of both Malygos and Sindragosa merged together to create this phenomenon. \n\nQuickly, we must make for the Azure Archives and inform Kalecgos and Sindragosa of this!\n\nTogether, we may be able to finally give them the peace that they deserve.", completion = "I am glad you recovered the essences of Sindragosa and Malygos. \n\nI never imagined trying to place their spirits to rest would lead to this.", objectives = "Meet Kalecgos back within the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72950] = { id = 72950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Conflict", description = "Malygos and myself both suffered horribly violent ends. The remains of our essences have been trapped in an endless loop.\n\nThey must be reformed, and broken out of that loop. To do so will require a tremendous amount of concentrated power.\n\nWe will have to utilize every amount of arcane energy within the Azure Archives... along with all of the assembled blue dragons.\n\nIt is the only chance we have to reform these spirits... and to put an end to their suffering.", completion = "Malygos and Sindragosa's spirits can finally rest. Thank you once more for all of your aid, {name}.\n\nThere is one last thing that must be done.", objectives = "Subdue the restless spirits of Malygos and Sindragosa within the Azure Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72951] = { id = 72951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Peaceful Farewell", description = "It brightens my heart to see everyone reunited, and Malygos and Sindragosa at peace at long last. \n\nIt is time that I give you all one last gift, something the blue dragons have not seen in quite some time.\n\nThe peaceful passing of one of their own.\n\nIt is my time, {name}. I should have flown beyond some time ago, but I could not leave with my kin still in disarray. \n\nWould you do an old dragon the honor of seeing me off on one last adventure?", completion = "Senegos... what a tremendous gift he's given to us all. \n\nThank you, {name}. I don't know if I could have united the blue dragons without you--and for that I will be forever grateful.\n\nIt's time for me to lead everyone forward.", objectives = "Speak with Senegos one last time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72952] = { id = 72952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scary Vault of Ur", description = "Tacha's big ears heard some noise in one of the tunnels. We took a peek inside. I'm not going to lie: it's grim in there. Pretty terrifying. All sorts of horrible creatures. Not the sort of thing Tacha and I usually deal with up close.\n\nYou have experience dealing with monsters, right? Excellent. You go first. Don't worry. Once it's safe, we'll come in and join you. Really, it's the least we can do.", progress = "Have you explored the vault?", completion = "Good work in there. Very brave. As long as we have more keys, we'll have more to explore. \n\nNot all of the vaults are terrifying, of course. Deadly? Sure. Treacherous? You bet. But maybe not as terrifying. Maybe.\n\nKeep in touch. In a few more days, we'll be ready to explore another vault.", objectives = "Enter and explore Zskera Vault: Ur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72953] = { id = 72953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zskera Vault: Az", description = "We have discovered a series of vaults below the island. Neltharion hoarded treasures, accumulated knickknacks, and stashed away the results of his failed experiments.\n\nWhen I say he's a hoarder, I'm not kidding! He filled chamber after chamber, and in time, they were all forgotten... until now. Treasure awaits us behind these locked doors! Also, the occasional deathtrap. Also, treasure! Now we have the keys to unlock those doors.", progress = "Have you explored the vault?", completion = "Well done. As long as we keep finding keys, we can keep exploring. In a few days, I'm sure we'll explore another vault.\n\nI think the names of these vaults are numbered. Az, Ur, Ix, Kx... those words must mean something. Don't get me wrong, I'm focused on the treasure, but I wouldn't mind learning a thing or two along the way... or is it \"a thing or Ix\"? Maybe it is.", objectives = "Enter and explore Zskera Vault: Az.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72954] = { id = 72954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zskera Vault: Ix", description = "Wulferd spotted some pirates making their way into the vaults this morning. If we don't act fast, they'll strip the vault clean!\n\nWe're going into the vault immediately. There's no time to lose. Will you be joining us?", progress = "Have you explored the vault? I'm worried about those pirates.\n\nYou're probably expecting me to make some pirate joke about \"arrrr-tifacts,\" but I have too much self-control for that. i do, however, think the treasure we find will be... \"booty-full.\" Okay, back to work.", completion = "Good work in there. We can continue this exploration as long as we have keys. In a few days, we'll explore another vault.\n\nEver since the storms died and Raszageth left, it's been a rush to grab as much as we can. Sadly, we're not the only folks rushing to grab it all. It's a good thing you're here to help us deal with that.", objectives = "Enter and explore Zskera Vault: Ix", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72955] = { id = 72955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zskera Vault: Kx", description = "I was afraid this might happen. The Sundered Flame is here. And they've discovered the Vaults.\n\nOf course, we have to stop them. Anything useful or dangerous, they're going to take straight to Sarkareth.\n\nI've had enough of his nonsense. Time for you to do what you do best.", progress = "Have you explored the vault?", completion = "Good work in there. As long as we find more keys, we can continue exploring. And then it's only a matter of time until we find another vault to explore... a few days, I'll bet.\n\nOh, and good luck with the Sundered Flame. I hate to see dracthyr fighting dracthyr... especially when we can be uncovering the secrets of the past instead. Stay safe out there.", objectives = "Enter and explore Zskera Vault: Kx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72956] = { id = 72956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Doors To Open", description = "There are still more vaults, but there aren't enough of us to explore them all.\n\nThat's where you come in. Could you look for more keys? Then we can continue exploring the vaults.\n\nTacha and I will stay here and work on documenting our earlier discoveries. That's tough work, but one of us has to do it. Okay, two of us. But it is a lot of work, I assure you.", progress = "Have you explored the vault?", completion = "Look at you! Opening doors! Having adventures! That's... a-door-able.\n\nSorry. Long day. Good work in there. As long we have keys, we'll find more adventure. And I'm fairly sure we'll find another vault in a few days. \n\nYou and me! And Tacha! Exploring the unknown. Well, mostly you, but we're helping.", objectives = "Enter and explore additional Zskera Vaults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72958] = { id = 72958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save-A-Mole", description = "Perisimona told me about her life-mate, Tuberros, and what she knows about his disappearance.\n\nTuberros was guiding a client from the Dragonscale Expedition around some ruins here. It sounds as though they may have run into the Sundered Flame.\n\nI would rather not go after the Sundered Flame myself. Doing so would announce my presence to Sarkareth. \n\nWill you aid us by finding and rescuing Tuberros and his client? Maybe then he can help guide us to Neltharion's vault.", completion = "It is time to get back to why we are here, and that is finding Sarkareth.\n\nI will send the niffen and Rannan back to Loamm, where it is safe.", objectives = "Find and save Tuberros and his uplander client.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72959] = { id = 72959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whose Vault Is It Anyway?", description = "I do not know what we will find in the vault or why Sarkareth wants access to it, but I hope we are not too late.\n\nBefore we continue any further, Tuberros should lead Rannan and Perisimona back to Loamm.\n\nCome and talk to me once you are ready to move forward.", completion = "I still think we should have sent them back to Loamm, but I trust Ebyssian's judgement.", objectives = "Talk to Emberthal once you are ready to go.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72961] = { id = 72961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charging Up", description = "Emberthal wanted this guy Sarkareth dealt with yesterday. I understand! I hate waiting too!\n\nThis door is frustratingly hard to crack... But! I have a plan because I always have a plan! My recipe for success is being one step ahead of everyone else. It's worked for me so far! Sorta.\n\nSo, about this plan... I might need your help!", progress = "Were you able to get me some of those orbs?", completion = "Tuberros is a life saver! These should do just fine! Now give me a moment to calculate the energy flux and... hmm... Yes... no, nope, ok, maybe...", objectives = "Gather 6 buzzing orb core for Rannan Korren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72962] = { id = 72962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open That Door!", description = "I am glad we are making progress but... I cannot shake a sense of foreboding of what awaits us inside. As Sarkareth learns about Neltharion, his intentions seem to get ever darker...\n\nI can only imagine what he is telling his people now--about me and about the other dracthyr. He will fracture our people forever.\n\nTalk to Rannan and see how much longer we have to wait. We can't waste more time.", completion = "Sarkareth would not have come here alone, {name}. I advise that you stay close and stay sharp.", objectives = "Talk to Rannan about his progress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72963] = { id = 72963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Upper Hand", description = "It troubles me that Dezran would sacrifice himself so willingly for Sarkareth... And that Amythora and Marithos would leave Dezran to save him.\n\nWe both know the loss of waking in a new world. But Sarkareth wallows in the darkness of our past. I cannot let him continue to recruit our people.\n\nSarkareth awaits in the next room. I do not wish to kill him, but we must bring him to justice.\n\nLet me know when you are ready.", completion = "I now feel only pity for Sarkareth. Nothing was left of him but an empty husk driven into madness.", objectives = "Defeat Scalecommander Sarkareth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72964] = { id = 72964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Singed", description = "Standing here, seeing these two Sundered Flame before me, there is no more anger. I see the confusion in their eyes and how they look at each other... They are so uncertain of their future.\n\nThey remind me of myself and the moment I emerged alone, my creche dead and forgotten by passing ages.\n\nI have to talk to them, {name}. Will you accompany me? As a friend?", progress = "I want to help them... be there for them when no one was there for me.", completion = "Perhaps I could help them cope with their feelings of abandonment. Maybe... I can reconcile my own past and lead them to a better future--one they deserve.", objectives = "Talk to Marithos and Amythora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72965] = { id = 72965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspects of Our Legacy", description = "I am proud to see that Emberthal is blossoming into a confident leader once more. Her people need her.\n\nBut that Sarkareth found Oathbinder is a reminder of the horrors of Neltharion's legacy and the folly of following him.\n\nI have a feeling that we will discover more than his trinkets and whispers here in these caverns.\n\nCome. We have much to discuss. Let us go back to Loamm and see if my brothers have found a way to subdue Fyrakk.", completion = "I am... startled by Ebyssian's censure. \n\nAny objects of power Neltharion was hoarding would have been a boon to us.\n\nBut he is right... if I want to be an Aspect, I need to show everyone what power the true heir to the black dragonflight holds.\n\nI will start with Fyrakk.", objectives = "Meet Ebyssian in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72966] = { id = 72966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where There's Smoke, There's Fire", description = "If you are finished indulging Ebyssian's associate, I would have us return to more pressing matters. \n\nLocating Fyrakk is still our primary mission. We cannot continue to delay it.\n\nI have discovered a massive caldera at the western edge of Zaralek. If Fyrakk is still here, then logic dictates that this volcanic area would be his hideout.\n\nMeet us there and we will proceed.", completion = "You found your way here. Good.\n\nWe have not seen Fyrakk yet, but we have seen djaradin. Many of them.", objectives = "Meet Ebyssian and Sabellian outside the Zaqali Caldera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72970] = { id = 72970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niffen and Goliath", description = "I didn't just come all the way out here to save your sniffers, ya know!\n\nThe deepflayers are vicious and stubborn, like obsidian ore. We've tried to lead them from our town by leaving out food and such, but they're all too keen to attack our sparrow caravans.\n\nIt's the big'un ruling over them that'll be trouble. Want to pay me back? Let's you, me, and your cologne-scented friend hunt it down together. I've got the perfect bait we can use too!", completion = "Yeesh! Certainly wasn't no lack of fight in that one, was there!", objectives = "Slay the Deepflayer Broodmatron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72972] = { id = 72972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waking Shores Reverse Tour", description = "It's time to send you backwards. Not backwards in time, although we could do that, but have you fly the courses in reverse.\n\nGet ready to see these courses in a different way.\n\nLet's start with Serohs Gnikaw!\n\nWait. Waking Shores!", completion = "Enjoying the new way of looking at things? Or do you not know if you're coming or going?\n\nEither way, let's get you off to the next set of races in the Ohn'ahran Plains.", objectives = "Fly each of the reverse courses in Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72973] = { id = 72973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smells Like Loamm", description = "I smelled you weren't a bad sort from the start. A little sweaty, but not a bad sort.\n\nConsider this your personal invitation to Loamm, home of the niffen!\n\nLet's all meet just outside the entrance. That way I can give you and your pals the proper niffen welcome!", progress = "You got Elder Honeypelt with you somewhere?\n\nHiding inside your boots, maybe?", completion = "Welcome to Loamm, Uplander! Our shining smell of a city!\n\nAurantia is the name. I'm the High Redolence around here, which is just a fancy way of saying I'm the leader. It also means I'll be protecting my people from all the trouble that's broken on through from above.\n\nBut, you know what? We've got time for all that later! Ebyssian and Emberthal have already filled me in, so why not take a second to rest up on a soft patch of dirt?", objectives = "Meet Elder Honeypelt in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72974] = { id = 72974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the City of Smells", description = "Ain't it incredible, uplander!\n\nNow for the backbreaking labor. We've got to deliver this deepflayer meat to all my customers and collect their pay. I'd carry it all myself, but I'm just a poor, old, frail, gorgeous woman in need now, aren't I?\n\n<Honeypelt gives you an expertly practiced wink.>\n\nWhy don't you handle it for me? Brynnsahce will do the heavy lifting while you take a little tour of the place. Put your best smell forward--we're a friendly sort!", progress = "It'd be a waste not to keep those nostrils open here in Loamm!", completion = "Not too shabby, kid. Maybe there's room for you on the monster hunting roster, yet!\n\nJust kidding! Another joke! There is no roster! Just combat-hungry suckers who got rocks rolling 'round their gut like I do.\n\nYou'll get there one day. Keep trying.", objectives = "Deliver deepflayer parcels around Loamm and return to Elder Honeypelt with the profits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72975] = { id = 72975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land Beneath", description = "I heard word you were aiding the green dragonflight, {name}.\n\nI bring word from Ebyssian.\n\nThe Life-Binder has news of the Incarnates, and she requests our presence at the Seat of the Aspects.\n\nThe black dragonflight will await you there. I will move on ahead to continue tracking our foe.", completion = "The Aspects have gathered. Let us not keep them waiting.", objectives = "Meet the black dragonflight at the Seat of the Aspects in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72976] = { id = 72976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crack in the World", description = "As you can see, Wrathion and Sabellian are also ready. If the Aspects have news of the Incarnates' actions, then the black dragonflight is prepared to answer the call.\n\nCome. They are eager to speak with us.", progress = "Wrathion and Sabellian made waiting for your arrival quite... tedious. \n\nI wish they could turn their boundless enthusiasm for bickering toward worthier means. Perhaps they just need the motivation.", completion = "I have read what I can about the Incarnates. \n\nFyrakk is every ounce as powerful as Iridikron, only lacking the discipline to focus that strength into singular goals. He would be just as happy burning his own followers down as he would our people.  \n\nThis will be a fight that all the Isles' denizens have a stake in.", objectives = "Speak with Alexstrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72977] = { id = 72977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Flames Fell", description = "The Aspects have requested our help. As protectors of the Isles and dragonkind, we are more than willing.\n\nI must locate Emberthal and ask her to join. I believe I can recruit her to our cause as long as we remain committed to hers against the Sundered Flame in the future.\n\nMeet Sabellian and Wrathion at the site of the Incarnates' devastation.", completion = "Perfect timing, {name}!\n\nIt would seem my efforts to investigate the area are not welcome. Would you mind helping me straighten out this situation?", objectives = "Meet Sabellian and Wrathion in Cascades Canyon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72978] = { id = 72978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scar of Earth and Fire", description = "This centaur practically attacked us upon our arrival. He seems quite protective over this burning pile of ashes.\n\nI know you have worked alongside the Shikaar before. Would you speak to him? I would like to confirm what happened here.\n\nThere is no chance that this is all a coincidence. If it connects to the Incarnates at all, we must learn all we can.", progress = "Have you learned anything of value?", completion = "I begin to see why Fyrakk was sealed away...\n\nYour assistance, as always, has been invaluable.", objectives = "Investigate the scene.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72979] = { id = 72979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earth Gives Way", description = "You may stay here to see what comes of this relic, or meet me afterward in Loamm. That is Honeypelt's home, which she offered us respite at while you were still in the cave.\n\nI would only ask that you check on Wrathion. He may be a ceaselessly buzzing pest, yes, but... these recent events force me to admit I care for his well-being too.  \n\nThere are only so many black dragons left. We must look out for each other.", completion = "Is that depressing lump of moods, Sabellian, alright?\n\n...What? I care enough to at least ask about him!", objectives = "Speak with Wrathion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72980] = { id = 72980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother's Keeper", description = "By my scales, I needed that win! That blasted Incarnate swatting us like flies did a number on my ego, and I assume Sabellian feels no different. \n\nAs infuriating as I find his lack of humor, groaning voice, and ugly shoes... I would ask that you check in on him. He is still family, after all, and I do not wish him to become dinner to these deepflayers.\n\nMeet Honeypelt and I outside these dreadful nests when you finish up with Sabellian.", completion = "I could hear you and Wrathion's yawping from all the way over here.\n\nIf you have finished with all that, why not take a look at this, {name}.", objectives = "Speak with Sabellian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72981] = { id = 72981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Patience of Princes", description = "The centaur's report of Primalist forces pushing into the underground after Fyrakk changes the situation. Wrathion and I believe it would be a tactical mistake to dawdle here any longer, waiting for Ebyssian and his devotee to arrive.\n\nWe still wish for you to join us. If you are ready, then we three should proceed together.", completion = "To say you smell lost is an understatement!", objectives = "Delve underground and fell the Primalist blockade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72982] = { id = 72982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ohn'ahran Plains Reverse Tour", description = "Time to go forward to go backward once more.\n\nMore races await you in Ohn'ahran plains. Head over there now, make sure you go in the right direction.", completion = "I think you're getting the hang of going backwards.\n\nOnto the Azure Span!", objectives = "Fly each of the reverse courses in Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72984] = { id = 72984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azure Span Reverse Tour", description = "The next set of backward courses are back in the Azure Span.\n\nWhen you're ready you should head back over there and retrace your previous steps to the previous races.", completion = "More courses undone, well done!\n\nOnto Thaldraszus for the last set of challenges!", objectives = "Fly each of the reverse courses in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72985] = { id = 72985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thaldraszus Reverse Tour", description = "Once more you'll be heading back to where it all finished. Or started. I can't remember anymore.\n\nSeek out my bronze colleagues to fly the reverse courses to complete your rewinding.", completion = "Who are you? I don't think we've met before.\n\nI'm joking. Well done on completing the newest tour.\n\nFeel free to re-fly any of the courses to beat your own best times. The sky's the limit!", objectives = "Fly each of the reverse courses in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72987] = { id = 72987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here We Go Again", description = "I understand Alexstrasza's concerns. Shadowflame is a vile force that poses an indescribable threat to anyone who comes close to it, as we have personally witnessed. Unfortunately, Aberrus may contain even more threats.\n\nWe need to continue to push forward.\n\nBefore I left Zaralek Cavern, I made contact with soldiers stationed by Neltharion at the Obsidian Rest. Luckily for us, they remain loyal to the Black Dragonflight. \n\nLet us meet there.", completion = "I am glad you were able to join us, {name}.", objectives = "Meet Ebyssian in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72988] = { id = 72988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Booty Bay Journal", completion = "Get your hands off me! Oh, wait a minute... you're not from around here.", objectives = "Speak to Senegos to temporarily neutralize your standing with Booty Bay, and then find Zeros in Booty Bay in the Eastern Kingdoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72989] = { id = 72989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruby Hatchling", description = "An egg from the red dragonflight is ready to hatch.\n\nReport to Amella in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Ruby Oathstone to hatch in a location strong with our flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", progress = "Have you brought the newest hatchling?", completion = "I am absolutely thrilled! All of my training has more than prepared me for one of my own flight.", objectives = "Collect the Red Dragon Egg at the Ruby Lifeshrine then hatch it at the Ruby Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72990] = { id = 72990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crimson Comfort", description = "I am looking forward to our red whelp. They are, after all, my specialty!\n\nI have already spoken with Amella, and I would like to handle the nest myself. Here is a list of materials. Bring them to me when you are done, and I can fashion the most comfortable cushion you have ever seen!\n\n<Lasztak hands you a list of supplies.>", progress = "Red whelplings are my specialty.", completion = "How comfortable. A cushion worthy of Queen Alexstrasza herself!", objectives = "Gather supplies for the Ruby Hatchling's nest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72991] = { id = 72991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warm Dragonfruit Pie", description = "When I think of red dragon comfort food, I immediately think of the pies back at the Ruby Life Pools. You can always tell when our blacksmith, Krendisc, has downtime between orders--the entire mountain smells of delicious baked dragonfruit!\n\nMy pie may not be as good as his, but I am sure our ruby hatchling will love it. If you bring me the ingredients I will bake the best pie I can!", progress = "<Lasztak cracks his knuckles.>\n\nIt has been a while since I baked anything, but I am confident!", completion = "When it comes to taking care of red dragons, I know what I am doing!", objectives = "Gather Ripened Dragonfruit near the Ruby Life Pools and Pre-Made Pie Crust from Erugosa in Valdrakken, then bring them to Lasztak to bake a pie for the Ruby Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72992] = { id = 72992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're Playing Wrong!", description = "Our red hatchling seems to be having quite the trouble making friends. Any time she tries to get one to play, it tends to end quickly.\n\nShe can be a bit pushy, but whelps are whelps. Why don't you get her in the right mindset to play with some tag?", progress = "Every whelp loves a game of tag!", completion = "<Agapanthus sighs.>\n\nI can already tell that whelp is going to be quite the handful.", objectives = "Play with the Ruby Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72993] = { id = 72993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm the Boss!", description = "Never have I met such a bossy child!\n\nShe has a list. A list! Please, take Belastrasza off our claws for a bit. I just... I need to sit down.", progress = "<The bags under Agapanthus's eyes are even deeper than usual.>", completion = "Not only does she need to learn patience, but she also needs to learn that she is not the center of the universe!", objectives = "Assist Belastrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72994] = { id = 72994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cavalier Pet", description = "I believe that the only way we can teach Belastrasza to be less self-obsessed is to show her firsthand how it makes others feel.\n\nVorquin are beautiful creatures, but they are incredibly high maintenance companions who need a lot of care.\n\nLysindra in Valdrakken has a baby vorquin for Bela. Perhaps she will learn through getting a taste of her own medicine.", progress = "A stubborn pet for a stubborn whelp.", completion = "This pet should teach Bela to be less stubborn... or just make twice the work for poor Lasztak. Well, one of them will learn from this.", objectives = "Obtain a Baby Vorquin battle pet for Belastrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72995] = { id = 72995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patience, Please", description = "Belastrasza has learned much through her vorquin foal, but I have thought of one more lesson that should be excellent for her.\n\nHer lack of patience has been stumping me for quite some time. Recently I was reflecting by the water, watching the turtles go about their day. Then I was hit by a revelation!\n\nWurallie has the perfect battle to test Belastrasza's patience, but poor Princess Vorquistrasza doesn't have the endurance. Can you meet them in the Waking Shores to lend a hand?", progress = "Slow and steady, Bela. Slow and steady.", completion = "She has truly come a long way since arriving at the daycare. While she still has more to learn, I am extremely proud of her.\n\nShe has expressed a desire to accompany you on your adventures. I hope she will not order you around too much.", objectives = "Help Belastrasza learn patience by defeating a turtle in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72996] = { id = 72996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bronze Hatchling", description = "An egg from the bronze dragonflight is ready to hatch.\n\nReport to Xius in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Bronze Oathstone to hatch in a location strong with their flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", progress = "Have you brought the newest hatchling?", completion = "Ah, a bronze whelp.\n\nLet us hope they stay in whelp form, hmm?", objectives = "Collect the Bronze Dragon Egg at the Ruby Lifeshrine then hatch it at the Bronze Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72997] = { id = 72997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Like a Sandy Nap", description = "While red dragons enjoy their surroundings lush and lively, bronze dragons prefer their environments dry and sandy. I am sure you can find many materials for our hatchling's nest in the Temporal Conflux in Thaldraszus.\n\nI have read that bronze whelps also enjoy an appropriately sized basin to curl themselves in. My friend at the inn in the Bronze Enclave has exclaimed often about an excess of bowls... I am sure she would not mind if we took one off her hands.", progress = "Bronze dragons are like cats. They defy time and space.", completion = "I cannot say that I quite understand the bronze flight's predilection for sandy environs... I find that the granules get everywhere.", objectives = "Gather supplies for the Bronze Hatchling's nest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72998] = { id = 72998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisanal Aging", description = "I have been learning much about bronze dragons since arriving in Valdrakken. While they take their charge of time seriously, they have found many hobbies for their free time that their magic can aid them with.\n\nMy friend Gorgonzormu swears by his cheeses for all stages of dragon life. He mentioned that he has a type of parmesan that is excellent for bronze whelps. It seems that our hatchling's first meal is figured out!", progress = "Cheese is best when aged over time, but bronze dragons have perfected rapid aging with their control of time!", completion = "Not only can bronze dragons age cheese quickly, but they can also digest it more rapidly!", objectives = "Buy Temporal Parmesan from Gorgonzormu in Valdrakken for the Bronze Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72999] = { id = 72999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here? There? Everywhere!", description = "Our bronze hatchling has been staying away from the other whelps, mostly hanging out in the sand. Sometimes we find him in the sandbox with the others, but we never see him moving around!\n\nHe could use some friendship. Why don't you treat him to a game of tag?", progress = "Every whelp loves a game of tag!", completion = "Those are some strong allergies. We may need to find some medication for this one.", objectives = "Play with the Bronze Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73000] = { id = 73000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneezing Through Time", description = "Zhusa is throwing us for quite the loop, {name}.\n\nSince he is so young, his control over time is not fully developed. Unfortunately, he has a strange reflex. Every time he sneezes he disappears, popping up elsewhere in any form! To top it off, he seems to have many allergies.\n\nPlease, help Zhusadormu figure out what he is allergic to so we can keep him in one place!", progress = "<Agapanthus rubs his temples.>\n\nOh, bronze whelps...", completion = "So Zhusadormu is allergic to... everything?\n\nThis may be more troublesome than we thought.", objectives = "Find Zhusadormu throughout Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73001] = { id = 73001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scaly Pet", description = "We have been trying to decide on the perfect pet for Zhusadormu. His allergies limit our options by quite a bit, but I believe I have thought of a pet for him.\n\nI know for a fact that Zhusa is not allergic to scales. A baby hornswog is hypoallergenic and I believe Lysindra could acquire one for us.", progress = "The whelps love hornswogs. They will love having one in the daycare!", completion = "A bronze hornswog for a bronze whelp. A perfect fit!", objectives = "Obtain a Baby Hornswog battle pet for Zhusadormu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73002] = { id = 73002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporal Immunity", description = "Zhusadormu has been trying hard to keep his powers in check.\n\nWhile we may not be able to prevent his allergies, he does not have to jump through time with each sneeze.\n\nWurallie believes she can test his control. Please go to the Waking Shores and help them with this lesson.", progress = "I believe in Zhusa. I hope you do too.", completion = "A sneeze without a teleport! A breakthrough to be proud of.\n\nNow that he won't get lost, Zhusadormu will want to join you on some quests", objectives = "Help Zhusadormu confront his allergies during a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73003] = { id = 73003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azure Hatchling", description = "An egg from the blue dragonflight is ready to hatch.\n\nReport to Axkall in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Azure Oathstone to hatch in a location strong with our flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", progress = "Have you brought the newest hatchling?", completion = "It is nice to care for a hatchling from my own flight. He reminds me of my days in Azsuna.", objectives = "Collect the Blue Dragon Egg at the Ruby Lifeshrine then hatch it at the Azure Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73004] = { id = 73004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scholar's Delight", description = "Blue dragons are seekers of knowledge, even from an early age. They seem drawn to books and scrolls, finding the most comfort when surrounded by them.\n\nFor our azure hatchling, the best nest is truly amongst our many books. I request that you collect the following for his nest--a quill of his own to learn to write, something to keep him nice and cold, and a bedtime story from Azure Span. I have heard tale of one that many blue dragons remember fondly.", progress = "I have raised dozens of blue whelps at all stages of life. At this point, their needs are second nature to me.", completion = "A nest amongst the books--perfect for a young blue dragon.", objectives = "Gather supplies for the Azure Hatchling's nest. \n\nAwakened Frost can be collected from many elementals across the Dragon Isles, created by combining 10 Rousing Frost, or bought from the auction house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73005] = { id = 73005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Nutrition", description = "Yes, blue dragons eat normal food, but the most important part of their diet is magical in nature. Wherever the blue flight can be found, you can be sure there is a source of nutritious ley crystals nearby.\n\nOf course, the homelands of the blue dragons became home to many others during their absence. The brackenhide gnolls have settled in our lands with the most ley crystals and taken them for themselves. You will need to enter their camps to reclaim the crystals for our whelp.", progress = "From the moment they hatch, dragons have incredibly sharp teeth.", completion = "The gnolls are not the first to steal our ley crystals, and they certainly will not be the last.", objectives = "Gather 6 Bite-Sized Ley Crystals from Brackenhide Hollow for the Azure Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73006] = { id = 73006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well, Actually...", description = "As expected, our dear blue whelp is quite the little \"bookwyrm\". I knew many hatchlings just like him in Aszuna, though we only had a small collection of scrolls.\n\nWhile there are books aplenty here in Valdrakken, whelps need to get up and moving! Why don't you play some tag?", completion = "Such a young whelp, yet so full of knowledge!", objectives = "Play with the Azure Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73007] = { id = 73007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Lenses", description = "Zalethgos is a bright child, but as he has gotten older we have realized something very clear about him.\n\nHe has terrible eyesight!\n\nHe is constantly speaking of things being fuzzy and of not being able to tell where one thing ends and the next begins.\n\nThere is a salon just across the bridge in Valdrakken. Please, accompany Zalethgos to try to find him the perfect pair of glasses to aid his vision.", progress = "I look forward to Zalethgos learning that sharp edges exist!", completion = "Zaleth seems absolutely thrilled with his new spectacles! He will surely flourish now.", objectives = "Bring Zalethgos to the Victorious Visage in Valdrakken to find a suitable pair of glasses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73008] = { id = 73008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scholar's Pet", description = "Long ago in Aszuna, young blue whelps from Azurewing Repose often studied magic alongside the elves of Nar'thalas Academy. I have many fond memories of the place, but one stands out among the others.\n\nThe enchanted books, while excellent to study, were quite the rascals. I have heard Lysindra acquired a similar book. I think this would be the perfect pet for Zalethgos!", progress = "Enchanted books are the perfect companions. They are full of magic, knowledge, and fun!\n\nAdditionally, you do not need to feed them.", completion = "I hope Zalethgos enjoys his new companion.", objectives = "Obtain an Enchanted Book pet for Zalethgos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73009] = { id = 73009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sight Isn't Everything", description = "Since getting his glasses, Zalethgos has been relying heavily on his eyesight. Of course, this is normal, but he needs to remain flexible in case he loses them.\n\nI believe it is time to turn out the lights. I think Wurallie has the perfect trick.\n\nShe believes she can teach Zalethgos to find victory even when he cannot use his eyes. Please join them in the Waking Shores.", progress = "In order to grow into a well-rounded dragon, Zalethgos must use everything at his disposal.", completion = "As proud as Zalethgos is of his glasses, knowing he can get along without them has given him new confidence. \nHe may want to join you on your adventures in the future.", objectives = "Help Zalethgos overcome his insecurity about his eyesight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73010] = { id = 73010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Hatchling", description = "An egg from the green dragonflight is ready to hatch.\n\nReport to Zahkrana in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Emerald Oathstone to hatch in a location strong with their flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", progress = "Have you brought the newest hatchling?", completion = "Every so often I would bring the whelps in my care to meet with some green whelps in Val'sharah.\n\nThey were always... so much calmer...\n\n<Agapanthus stares off into the distance.>", objectives = "Collect the Green Dragon Egg at the Ruby Lifeshrine then hatch it at the Emerald Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73011] = { id = 73011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Sweet Dirt", description = "Green dragons prefer a home that is both natural and mystical, imbued with the power of the Emerald Dream.\n\nThe Emerald Gardens will certainly have many materials with which to build an appropriate nest for this little one. Perhaps we should speak to a member of their flight to find something to bring them comfort as well.", progress = "We will have to maximize this hatchling's comfort to allow them to rest well and grow.", completion = "May this whelp grow roots strong and firm.\n\nNot literally, of course.", objectives = "Gather supplies for the Emerald Hatchling's nest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73012] = { id = 73012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochenblume Harvest", description = "Every green dragon loves a leafy, crunchy snack. The plants that grow with Dream exposure are densely packed with nutrients, keeping the greens healthy and content.\n\nHochenblume flowers are a sweet, delightful treat for young green dragons, and contain all the vitamins that a growing hatchling needs.", progress = "Not only are the hochenblume sweet on the tongue, but they also have a delightful aroma.", completion = "What a treat. They seem absolutely thrilled!", objectives = "Gather Hochenblume for the Emerald Hatchling. \n\nHochenblume can be looted from plant-based creatures, gathered with the Herbalism skill, or bought from the auction house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73013] = { id = 73013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So... Tired...", description = "I have some worries about our new green friend. They are not sleeping as much as most green whelps tend to do.\n\nThey seem to be having trouble sleeping. Why don't you get them up and moving around with a game of tag?", progress = "Every whelp loves a game of tag!", completion = "That poor whelp. We must get them some rest soon.", objectives = "Play with the Emerald Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73014] = { id = 73014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Green Who Can't Sleep?", description = "{name}... we have a problem.\n\nPosidriss has insomnia.\n\nI did not even know it was possible for a green dragon to not be able to fall asleep! How are they to learn to protect the Dream if they cannot enter it?\n\nPlease, try anything you can think of to help Posidriss fall asleep.", progress = "Every green dragon needs to be able to sleep!", completion = "We uh... we will keep working on it. We have to!", objectives = "Try to help Posidriss fall asleep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73015] = { id = 73015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sleepy Pet", description = "Posidriss's sleeping troubles are still causing them many problems. This is preventing them from developing their connection to the Dream.\n\nBears hibernate, bears dream, bear cubs are soft, warm and cuddly. Some of the cubs in the Dragon Isles are even connected to the Dream. Can you fetch one from Lysindra for Posidriss?", progress = "Where there are bears, there are druids. And where there are druids, there are green dragons!", completion = "Okay cub, please teach Posidriss your sleeping ways.", objectives = "Obtain a Bear Cub pet for Posidriss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73016] = { id = 73016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hibernation", description = "Posidriss's companion has been helping them with their severe insomnia, but I worry that they are still falling behind other whelps in their connection to the Dream.\n\nPerhaps we can aid them through a pet battle! Green dragons often protect the Dream from the Nightmare, and Wurallie has found the perfect critter for them to practice this on.\n\nIt is mostly harmless.", completion = "Posidriss was certainly enthusiastic about facing the enemies of the Emerald Dream. I think they learned a lesson as well.\n\nPosidriss will want to join you on some of your future adventures, though you may have to keep them from rushing after the big threats.", objectives = "Help Posidriss defeat the Nightmare critter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[73017] = { id = 73017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormsunder Crater Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
