quests[73026] = { id = 73026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booty Bay", description = "Land of pirates, swindlers, and raiders! Zeros, once just a captive whelpling, has built a mighty reputation as an auction house trader in one of the most cutthroat places on Azeroth.\n\nHowever, his recent investment blunder made the front page of the Booty Bay Journal. Rescue him before his debt is collected by the Baron.", completion = "You think I know anything about Booty Bay? Why yes, I do...", objectives = "Speak to Senegos for more information.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
