quests[73031] = { id = 73031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion of the Winterpelt", description = "Thank you for all that you have done, {name}.\n\nIt is all too easy to turn within and simply continue on as you always have.\n\nThe Winterpelt will rejoin the world. We will return to the path our ancestors strayed from.\n\nAnd we will never forget your part in this.\n\nI have gathered the tribe and our new allies together to celebrate. Speak with me when you are ready to begin.", progress = "Shall we begin?", completion = "Thank you, friend.", objectives = "Speak to Kranac to begin the celebration.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
